class RangeSet:
    def __init__(self, ranges=()):
        parsed = []
        for pair in ranges:
            start, end = pair
            self._check_bounds(start, end)
            if start < end:
                parsed.append((start, end))
        self._ranges = self._normalize(parsed)

    @staticmethod
    def _check_ints(*values):
