    @staticmethod
    def _check_bounds(start, end):
        _check_ints(start, end)
        if start > end:
            raise ValueError

    @staticmethod
    def _normalize(ranges):
        out = []
        for a, b in sorted(ranges):
            if out and a <= out[-1][1]:
